import assert from 'node:assert/strict';
import {readFile,writeFile,readdir} from 'node:fs/promises';
import {createRequire} from 'node:module';
import {dirname,resolve} from 'node:path';
import {createHash} from 'node:crypto';
import {chromium} from '@playwright/test';
const mode=process.argv[2],output=process.argv[3],require=createRequire(import.meta.url);
const test=require.resolve('@playwright/test/package.json'),pw=createRequire(test).resolve('playwright/package.json'),core=createRequire(pw).resolve('playwright-core/package.json');
const registry=JSON.parse(await readFile(resolve(dirname(core),'browsers.json'),'utf8'));
const headless=registry.browsers.find(x=>x.name==='chromium-headless-shell');
assert.equal(JSON.parse(await readFile(test,'utf8')).version,'1.64.0');assert.equal(headless.revision,'1248');
const result={mode,playwright:'1.64.0',revision:headless.revision,expectedVersion:headless.browserVersion,cache:process.env.PLAYWRIGHT_BROWSERS_PATH??'existing default host cache',rawBrowserError:null};let browser;
try {
 if(mode==='empty'){assert(process.env.PLAYWRIGHT_BROWSERS_PATH);assert.equal((await readdir(process.env.PLAYWRIGHT_BROWSERS_PATH)).length,0);}
 browser=await chromium.launch();
 assert.equal(mode,'control','An independently empty cache must not launch');
 result.actualVersion=browser.version();assert.equal(result.actualVersion,headless.browserVersion);
 const page=await browser.newPage();await page.setContent('<title>CI prerequisite control</title><p id="control">Real pinned Chromium launched</p>');
 result.actualDOM=await page.locator('#control').textContent();assert.equal(result.actualDOM,'Real pinned Chromium launched');result.userAgent=await page.evaluate(()=>navigator.userAgent);result.launchSucceeded=true;
 const full=chromium.executablePath();result.fullChromiumExecutable=full;result.fullChromiumExecutableSHA256=createHash('sha256').update(await readFile(full)).digest('hex');
} catch(error) {
 result.rawBrowserError=String(error);console.error(result.rawBrowserError);
 if(mode!=='empty')throw error;
 assert(result.rawBrowserError.includes("Executable doesn't exist"));assert(result.rawBrowserError.includes('chromium_headless_shell-1248'));result.expectedMissingCaptured=true;result.launchSucceeded=false;
} finally {if(browser){await browser.close();result.ownedBrowserClosedNormally=true;}await writeFile(output,JSON.stringify(result,null,2)+'\n');}
console.log(mode==='empty'?'ACTUAL_EMPTY_CACHE_MISSING_EXECUTABLE_CAPTURED_NOT_PRODUCT_PASS':'ACTUAL_PINNED_CHROMIUM_LAUNCH_AND_DOM_CONTROL_PASS');
